// 0/1 knapsack in O(W) space
int knapsack(int W, vector<int>& wt, vector<int>& val) {
    vector<int> dp(W + 1, 0);
    for (int i = 0; i < (int)wt.size(); i++)
        for (int w = W; w >= wt[i]; w--)          // high to low: use each item once
            dp[w] = max(dp[w], dp[w - wt[i]] + val[i]);
    return dp[W];
}

